const items = $input.all().map(i => i.json);

// Dedup usando static data de n8n (persiste entre ejecuciones)
const staticData = $getWorkflowStaticData('global');
const processed = staticData.processedCodes ?? [];

const newItems = items.filter(item => !processed.includes(item.codigo));

if (newItems.length === 0) {
  console.log('Sin items nuevos — todos ya procesados');
  return [];
}

// Guardar códigos procesados (máx 2000 para no desbordar memoria)
const updated = [...new Set([...processed, ...newItems.map(i => i.codigo)])].slice(-2000);
staticData.processedCodes = updated;

console.log(`Nuevos: ${newItems.length} | Ya procesados: ${items.length - newItems.length} | Total en memoria: ${updated.length}`);

// Construir prompt para cada item nuevo
return newItems.map(item => {
  const monto = item.montos?.monto_disponible_clp
    ? `$${Number(item.montos.monto_disponible_clp).toLocaleString('es-CL')} CLP`
    : 'No informado';

  const cierre = item.fechas?.fecha_cierre ?? 'No disponible';
  const competidores = item.resumen?.total_ofertas_recibidas ?? 0;
  const fechaCierre = item.fechas?.fecha_cierre
    ? item.fechas.fecha_cierre.split(' ')[0]
    : null;
  const urlMP = `https://www.mercadopublico.cl/Procurement/Modules/RFB/DetailsAcquisition.aspx?idlicitacion=${item.codigo}`;

  const userPrompt = `Analiza esta Compra Ágil para HE FORGE SpA y devuelve SOLO JSON:

CÓDIGO: ${item.codigo}
NOMBRE: ${item.nombre}
ORGANISMO: ${item.institucion?.organismo_comprador}
UNIDAD: ${item.institucion?.unidad_compra}
REGIÓN: ${item.institucion?.nombre_region}
MONTO: ${monto}
CIERRE: ${cierre}
COMPETIDORES: ${competidores}

JSON (sin markdown, sin texto extra):
{
  "score": <0-100>,
  "viabilidad": "alta|media|baja",
  "resumen": "<máx 2 líneas>",
  "justificacion": "<máx 3 líneas>",
  "riesgo": "<1 línea>",
  "accion": "cotizar|investigar|ignorar",
  "precio_sugerido_clp": <número o null>
}`;

  return { json: {
    codigo: item.codigo,
    nombre: item.nombre,
    organismo: item.institucion?.organismo_comprador ?? '',
    region: item.institucion?.nombre_region ?? '',
    monto_clp: item.montos?.monto_disponible_clp ?? null,
    fecha_cierre: fechaCierre,
    url_mp: urlMP,
    fecha_deteccion: new Date().toISOString().split('T')[0],
    user_prompt: userPrompt
  }};
});

const allInputs = $input.all();
const prompts = $('Construir Prompt').all();
const results = [];

const NOTION_TOKEN = 'Bearer PEGA_TU_NOTION_TOKEN';
const DATABASE_ID = '37217c326c5580788817ec44363e2577';

for (let i = 0; i < allInputs.length; i++) {
  const agentOutput = allInputs[i].json.output ?? allInputs[i].json.text ?? JSON.stringify(allInputs[i].json);
  const ctx = prompts[i].json;

  let scoring;
  try {
    const clean = agentOutput.replace(/```json|```/g, '').trim();
    const match = clean.match(/\{[\s\S]*\}/);
    scoring = JSON.parse(match ? match[0] : clean);
  } catch(e) {
    scoring = {
      score: 0, viabilidad: 'baja',
      resumen: 'Error al parsear IA',
      justificacion: String(agentOutput).substring(0, 200),
      riesgo: 'Error de parsing',
      accion: 'ignorar',
      precio_sugerido_clp: null
    };
  }

  const score = Number(scoring.score) || 0;

  if (score < 40) {
    continue;
  }

  // CHECK NOTION: ¿ya existe este código?
  try {
    const checkResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/databases/' + DATABASE_ID + '/query',
      headers: {
        'Authorization': NOTION_TOKEN,
        'Content-Type': 'application/json',
        'Notion-Version': '2022-06-28'
      },
      body: {
        filter: {
          property: 'Codigo',
          title: { equals: ctx.codigo }
        },
        page_size: 1
      }
    });

    if (checkResp.results?.length > 0) {
      console.log(`⏭️ YA EXISTE ${ctx.codigo} — score ${score}`);
      continue;
    }
  } catch(e) {
    console.error(`⚠️ Check Notion falló ${ctx.codigo}: ${e.message} — creo igual`);
  }

  // CREAR en Notion
  const properties = {
    "Codigo": { "title": [{ "text": { "content": ctx.codigo } }] },
    "Nombre": { "rich_text": [{ "text": { "content": ctx.nombre ?? '' } }] },
    "Score": { "number": score },
    "Viabilidad": { "select": { "name": scoring.viabilidad ?? 'baja' } },
    "Accion": { "select": { "name": scoring.accion ?? 'ignorar' } },
    "Estado Seguimiento": { "select": { "name": "pendiente" } },
    "Organismo": { "rich_text": [{ "text": { "content": ctx.organismo ?? '' } }] },
    "Region": { "rich_text": [{ "text": { "content": ctx.region ?? '' } }] },
    "Monto CLP": { "number": ctx.monto_clp ?? null },
    "Resumen": { "rich_text": [{ "text": { "content": (scoring.resumen ?? '').substring(0, 2000) } }] },
    "Justificacion": { "rich_text": [{ "text": { "content": (scoring.justificacion ?? '').substring(0, 2000) } }] },
    "Riesgo": { "rich_text": [{ "text": { "content": (scoring.riesgo ?? '').substring(0, 2000) } }] },
    "Precio Sugerido CLP": { "number": scoring.precio_sugerido_clp ?? null },
    "URL MP": { "url": ctx.url_mp ?? null },
    "Notificado Telegram": { "checkbox": false }
  };

  if (ctx.fecha_cierre) {
    properties["Fecha Cierre"] = { "date": { "start": ctx.fecha_cierre } };
  }
  if (ctx.fecha_deteccion) {
    properties["Fecha Deteccion"] = { "date": { "start": ctx.fecha_deteccion } };
  }

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/pages',
      headers: {
        'Authorization': NOTION_TOKEN,
        'Content-Type': 'application/json',
        'Notion-Version': '2022-06-28'
      },
      body: {
        parent: { database_id: DATABASE_ID },
        properties
      }
    });

    console.log(`✅ NUEVO ${ctx.codigo} — score ${score} — ${scoring.accion}`);

    results.push({ json: {
      notion_page_id: response.id,
      codigo: ctx.codigo,
      nombre: ctx.nombre,
      organismo: ctx.organismo,
      region: ctx.region,
      monto_clp: ctx.monto_clp,
      fecha_cierre: ctx.fecha_cierre,
      url_mp: ctx.url_mp,
      score,
      viabilidad: scoring.viabilidad ?? 'baja',
      accion: scoring.accion ?? 'ignorar',
      resumen: scoring.resumen ?? '',
      justificacion: scoring.justificacion ?? '',
      riesgo: scoring.riesgo ?? ''
    }});

    await new Promise(r => setTimeout(r, 350));

  } catch(err) {
    console.error(`❌ Notion ${ctx.codigo}: ${err.message}`);
  }
}

console.log(`Nuevos guardados: ${results.length} de ${allInputs.length}`);

if (results.length === 0) {
  return [{ json: { message: 'Sin items nuevos con score >= 40', total: allInputs.length } }];
}

return results;

