const TICKET = 'PEGA_TU_TICKET_MP';
const BASE = 'https://api2.mercadopublico.cl/v2/compra-agil';

let allItems = [];
let pagina = 1;
let totalPaginas = 1;
let reintentos = 0;

while (pagina <= totalPaginas && reintentos < 5) {
  let resp;
  try {
    resp = await this.helpers.httpRequest({
      method: 'GET',
      url: BASE,
      headers: { 'ticket': TICKET },
      qs: {
        ttl_cambio_ms: 43200000,
        region: '10,11,9',
        estado: 'publicada',
        tamano_pagina: 50,
        numero_pagina: pagina
      }
    });
  } catch (err) {
    if (err.message?.includes('429') || err.response?.status === 429) {
      reintentos++;
      console.log(`429 en página ${pagina} — reintento ${reintentos}/5, espero 5s`);
      await new Promise(r => setTimeout(r, 5000));
      continue;
    }
    throw err;
  }

  if (resp.success !== 'OK' || !resp.payload?.items) {
    throw new Error('API Error: ' + JSON.stringify(resp.errors));
  }

  totalPaginas = resp.payload.paginacion.total_paginas;
  allItems.push(...resp.payload.items);
  console.log(`Página ${pagina}/${totalPaginas} — ${resp.payload.items.length} items (total: ${allItems.length})`);

  reintentos = 0; // reset en éxito
  pagina++;

  // Pausa 2s entre páginas
  if (pagina <= totalPaginas) {
    await new Promise(r => setTimeout(r, 2000));
  }
}

const filtered = allItems.filter(item => (item.montos?.monto_disponible_clp ?? 0) > 0);
console.log(`Total: ${allItems.length} | Con monto > 0: ${filtered.length}`);

return filtered.map(item => ({ json: item }));
